#@ requires 1 == 1
    #@ ensures 1 == 1
    #@ assigns \nothing
    def find_append_targets(stmts: List[Dict[str, Any]]) -> Set[str]:
        result = set()
        n = len(stmts)
        i = 0
        #@ loop invariant 0 <= i and i <= n
        #@ loop variant n - i
        while i < n:
            stmt = stmts[i]
            if stmt.get("stmt") == "Expr":
                val = stmt.get("value", {})
                if val.get("type") == "Call":
                    func = val.get("func", "")
                    if func.endswith(".append"):
                        arr_name = func.rsplit(".", 1)[0]
                        result.add(arr_name.replace(".", "_"))
            j = 0
            #@ loop invariant 0 <= j and j <= 2
            #@ loop variant 2 - j
            while j < 2:
                if j == 0:
                    key = "body"
                else:
                    key = "orelse"
                if key in stmt:
                    result |= IRScanner.find_append_targets(stmt[key])
                j += 1
            i += 1
        return result
